{
  "decision": "NO_CHANGE",
  "workflow_yaml": null,
  "rationale": "The workflow is a one-time template-cleanup workflow that self-deletes (it removes .github/workflows/template-cleanup.yml) and only runs when the repository is not the template itself. The CI history shows every recorded run was skipped, confirming the repository-name guard prevents execution on this repo, so there is no successful-duration history or repeated execution to optimize. Evaluated candidate patterns: P-LIT-GHA-CACHE has no dependency-fetching steps to cache beyond checkout; P-LIT-CUSTOM-TIMEOUT requires representative successful-duration history, which is absent (all runs skipped); P-LIT-CANCEL-STALE is unsuitable because the workflow mutates the repository and deletes itself, so cancelling a stale run could leave partial cleanup state and there is typically only one run; P-LIT-IDLE-SCHEDULE and schedule-based patterns do not apply because there is no schedule trigger. No supported pattern has met preconditions for this workflow, and the intended build/test coverage (the cleanup itself) must be preserved unchanged.",
  "evidence_ids": ["P-LIT-GHA-CACHE", "P-LIT-CUSTOM-TIMEOUT", "P-LIT-CANCEL-STALE", "P-LIT-IDLE-SCHEDULE"]
}
